Lemma wr3_out : forall (m : word -> option byte) (a1 a2 a3 y0 y1 y2 : Z) (x : word),
  (0 <= a1)%Z -> (a1 + 4 <= 2 ^ 64)%Z -> (0 <= a2)%Z -> (a2 + 4 <= 2 ^ 64)%Z -> (0 <= a3)%Z -> (a3 + 4 <= 2 ^ 64)%Z ->
  ~ (a1 <= u x < a1 + 4)%Z -> ~ (a2 <= u x < a2 + 4)%Z -> ~ (a3 <= u x < a3 + 4)%Z ->
